// Procesar y formatear resultado del health check REST API
// Siempre generar un item, incluso si el HTTP Request falló
const items = $input.all();
const item = items.length > 0 ? items[0] : null;
const json = item?.json || {};
const error = item?.error;
const timestamp = new Date().toISOString();

// Determinar estado del servicio
let statusCode = json.statusCode || json.code || (error ? 'ERROR' : 200);
const hasError = error || (typeof statusCode === 'string' && statusCode.includes('ERROR')) || (typeof statusCode === 'string' && statusCode.includes('TIMEOUT'));
const isOk = !hasError && typeof statusCode === 'number' && statusCode >= 200 && statusCode < 400;

// Si no hay item, significa que el HTTP Request falló completamente
if (!item) {
  statusCode = 'TIMEOUT/NO_RESPONSE';
}

const estado = isOk ? 'exito' : 'error';
const nombreServicio = 'REST API';
const puerto = 3000;
const url = 'http://host.docker.internal:3000/up';
const errorMsg = error?.message || json.error || json.message || (hasError ? 'Servicio no disponible o timeout' : null);

// Construir mensaje descriptivo
let mensaje = `[${timestamp}] Health Check ${nombreServicio}\n`;
mensaje += `===========================================\n`;
mensaje += `${isOk ? 'OK' : 'ERROR'} ${nombreServicio} (puerto ${puerto}): ${isOk ? 'OK' : 'ERROR'}\n`;
mensaje += `   Status: ${statusCode}\n`;
if (!isOk && errorMsg) {
  mensaje += `   Error: ${errorMsg}\n`;
}
mensaje += `   URL: ${url}\n`;
mensaje += `===========================================\n`;

return {
  json: {
    tipo: 'health-check',
    mensaje: mensaje,
    estado: estado,
    fecha_ejecucion: timestamp,
    servicio: 'rest',
    nombre_servicio: nombreServicio,
    puerto: puerto,
    statusCode: statusCode,
    error: errorMsg,
    url: url
  }
};

